MATCH (v:AngleBallValve:PlantItem {unit_id: '288'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'H-9301'}), (b:PlantItem {tag: 'E-9301'}), (r:PlantItem {tag: 'R-9301'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x <> r AND y <> r)+ (b)
}
RETURN a.tag AS source_tag, b.tag AS destination_tag

MATCH (a:PlantItem {tag: 'P-7202'}), (b:PlantItem {tag: 'D-7201'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
                    WHERE x.tag <> 'CHV-72005' AND y.tag <> 'CHV-72005')+ (b)
       } AS reachable

MATCH (tank:PlantItem {tag: 'TK-18004'})-[:line_to]-(v:Valve)<-[:control]-(actuator:PlantItem)<-[:send_signal_to*]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-18504'}), (b:PlantItem {tag: 'P-18501A'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (item:PlantItem {tag: 'TK-15901'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'TK-25002'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
