MATCH (:PlantItem {tag: 'E-52102'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'E-22502'}), (b:PlantItem {tag: 'P-22601B'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'T-22501')+ (b)
       } AS reachable

MATCH (i:PlantItem {tag: 'EA-35501'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (f:ProcessInstrumentationFunction {loop_tag: 'FSLL-224023'})-[:send_signal_to*]->(a:PlantItem {kind: 'actuator'})-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'H-22001'}), (b:PlantItem {tag: 'R-22001'})
RETURN a.tag AS source_tag, b.tag AS target_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (e:PlantItem:AirEjector {unit_id: '239'})
RETURN e.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'R-27301'}), (b:PlantItem {tag: 'P-27302'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v) AS valve_count, collect(DISTINCT v.tag) AS valve_tags

MATCH (t:PlantItem {tag: 'T-21701'})-[:line_to]-(v:Valve)<-[:control]-(a:PlantItem {kind: 'actuator'})<-[:send_signal_to*1..]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-25201'}), (b:PlantItem {tag: 'E-25302'}), (v:PlantItem:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag(final

MATCH (a:PlantItem {tag: 'P-25201'}), (b:PlantItem {tag: 'E-25302'}), (v:PlantItem:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-13103'}), (b:PlantItem {tag: 'F-13302'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (a:PlantItem {tag: 'P-49201B'}), (b:PlantItem {tag: 'EA-49501'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'K-7501'}), (b:PlantItem {tag: 'V-7601'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'CHV-74001' AND y.tag <> 'CHV-74001')+ (b)
}
RETURN b.tag AS tag

MATCH (a:PlantItem {tag: 'TK-34703'}), (b:PlantItem {tag: 'TK-35201'})
RETURN EXISTS {
  MATCH (a)-[:line_to*1..]->(b)
  WHERE NOT EXISTS {
    MATCH (a)-[:line_to*1..]->(v:PlantItem {tag: 'V-34801'})-[:line_to*1..]->(b)
  }
} AS can_flow_without_valve, a.tag AS from_tag, b.tag AS to_tag, 'V-34801' AS avoided_tag

MATCH (a:PlantItem {tag: 'D-18401'}), (b:PlantItem {tag: 'TK-19001'})
OPTIONAL MATCH (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v.tag) AS valve_count, collect(DISTINCT v.tag) AS valve_tags

MATCH (a:PlantItem {tag: 'P-30701'}), (b:PlantItem {tag: 'TK-31703'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
    WHERE x.tag <> 'V-31601' AND y.tag <> 'V-31601')+ (b)
} AS can_flow_without_valve

MATCH (a:PlantItem {tag: 'V-21001'}), (b:PlantItem {tag: 'V-23401'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (a:PlantItem {tag: 'E-23101'}), (b:PlantItem {tag: 'EJ-23102B'})
RETURN EXISTS {
  MATCH p = shortestPath((a)-[:line_to*1..]->(b))
  WHERE NONE(n IN nodes(p) WHERE n.tag = 'D-23101')
} AS reachable_without_D23101

MATCH (v:PlantItem:GateValve {line_number: '6-PG-2160026-A1A-N'})-[:line_to*1..]->(tv:PlantItem {tag: 'TV-215001'})
RETURN DISTINCT v.tag AS tag, coalesce(v.operating_position, 'NO') AS normal_position
ORDER BY tag;

MATCH (b:PlantItem:ButterflyValve {line_number: '6-P-4850004-B1A-N'}), (x:PlantItem {tag: 'XV-486001'})
WHERE EXISTS { (b)-[:line_to*1..]->(x) }
RETURN DISTINCT b.tag AS tag, coalesce(b.operating_position, 'NO') AS normal_operating_position ORDER BY tag

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(d:PlantItem {tag: 'D-17301'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(e:PlantItem {tag: 'EA-22001'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(tank:PlantItem {tag: 'TK-3203'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(:PlantItem {tag: 'EJ-50201A'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;
